async def act(page):
    import re

    # Navigate (relative) to the Orders by Period report
    await page.goto('/index.php/admin/report_sales/order/period/')
    await page.wait_for_timeout(1000)

    # 1) Attempt to set the Period combobox to a "Month" option (preserve exact option text)
    comboboxes = page.get_by_role('combobox')
    try:
        cb_count = await comboboxes.count()
    except Exception:
        cb_count = 0

    for i in range(cb_count):
        cb = comboboxes.nth(i)
        try:
            options = await cb.evaluate("el => Array.from(el.options).map(o => o.text)")
        except Exception:
            options = []
        for opt_text in options:
            if opt_text and 'month' in opt_text.lower():
                # select by exact visible label read from the DOM (robust to NBSP)
                try:
                    await cb.select_option(label=opt_text)
                except Exception:
                    # narrow fallback: select by option value
                    try:
                        value = await cb.evaluate("(el, target) => { const o = Array.from(el.options).find(x => x.text === target); return o && o.value; }", opt_text)
                        if value:
                            await cb.select_option(value=value)
                    except Exception:
                        pass
                # stop searching comboboxes once we've attempted selection
                break
        else:
            continue
        break

    # 2) Attempt to set From/To date inputs to cover 2022-05-01 -> 2022-12-31
    textboxes = page.get_by_role('textbox')
    try:
        tb_count = await textboxes.count()
    except Exception:
        tb_count = 0

    from_set = False
    to_set = False
    for i in range(tb_count):
        if from_set and to_set:
            break
        tb = textboxes.nth(i)
        try:
            info = await tb.evaluate("el => ({ id: el.id||null, name: el.name||null, aria: el.getAttribute('aria-label')||null, placeholder: el.placeholder||null, type: el.type||null })")
        except Exception:
            info = None
        label_candidates = ''
        if info:
            label_candidates = ' '.join([str(info.get(k) or '') for k in ('id', 'name', 'aria', 'placeholder', 'type')]).lower()
        try:
            if (not from_set) and any(x in label_candidates for x in ('from', 'start')):
                # try ISO format first
                try:
                    await tb.fill('2022-05-01')
                except Exception:
                    try:
                        await tb.fill('05/01/2022')
                    except Exception:
                        pass
                from_set = True
                continue
            if (not to_set) and any(x in label_candidates for x in ('to', 'end')):
                try:
                    await tb.fill('2022-12-31')
                except Exception:
                    try:
                        await tb.fill('12/31/2022')
                    except Exception:
                        pass
                to_set = True
                continue
        except Exception:
            pass

    # Positional fallback: fill first two textboxes if explicit fields not detected
    if not (from_set and to_set):
        filled = 0
        for i in range(tb_count):
            if filled >= 2:
                break
            tb = textboxes.nth(i)
            try:
                if not from_set:
                    try:
                        await tb.fill('2022-05-01')
                    except Exception:
                        await tb.fill('05/01/2022')
                    from_set = True
                    filled += 1
                    continue
                if not to_set:
                    try:
                        await tb.fill('2022-12-31')
                    except Exception:
                        await tb.fill('12/31/2022')
                    to_set = True
                    filled += 1
                    continue
            except Exception:
                continue

    # 3) Click an apply/show button to refresh the report (try common labels)
    submit_names = ['Show Report', 'Show', 'Refresh', 'Apply', 'Submit', 'Go']
    clicked = False
    for name in submit_names:
        try:
            btn = page.get_by_role('button', name=name)
            if await btn.count() > 0:
                try:
                    await btn.nth(0).click()
                    clicked = True
                    break
                except Exception:
                    pass
        except Exception:
            pass

    if not clicked:
        try:
            all_buttons = page.get_by_role('button')
            bc = await all_buttons.count()
            for i in range(bc):
                try:
                    b = all_buttons.nth(i)
                    name_attr = await b.get_attribute('aria-label') or ''
                    text = name_attr.strip() or (await b.inner_text() or '').strip()
                    if text and any(w in text.lower() for w in ('show', 'refresh', 'apply', 'submit', 'go')):
                        try:
                            await b.click()
                            clicked = True
                            break
                        except Exception:
                            continue
                except Exception:
                    continue
        except Exception:
            pass

    # allow the report to refresh
    await page.wait_for_timeout(1400)

    # 4) Capture accessible table(s) and extract raw text for parsing
    tables = page.get_by_role('table')
    try:
        tcount = await tables.count()
    except Exception:
        tcount = 0

    snapshot_text = ''
    if tcount > 0:
        parts = []
        for i in range(tcount):
            try:
                parts.append(await tables.nth(i).inner_text())
            except Exception:
                continue
        snapshot_text = '\n'.join(parts)
    else:
        try:
            regions = page.get_by_role('region')
            if await regions.count() > 0:
                snapshot_text = await regions.nth(0).inner_text()
            else:
                snapshot_text = await page.content()
        except Exception:
            snapshot_text = await page.content()

    # normalize NBSP
    snapshot_text = snapshot_text.replace('\u00A0', ' ').replace('\xa0', ' ')

    # 5) Conservative parsing for May..Dec 2022
    month_map = {'May': '05', 'June': '06', 'July': '07', 'August': '08', 'September': '09', 'October': '10', 'November': '11', 'December': '12'}
    results = {v: '0' for v in month_map.values()}

    lines = [ln.strip() for ln in snapshot_text.splitlines() if ln.strip()]

    for mname, mm in month_map.items():
        count = None
        # Pattern 1: 'MonthName 2022' followed by a number on the same line
        p1 = re.compile(rf'{mname}\s+2022[^0-9\n\r]*([0-9,]+)', re.I)
        m = p1.search(snapshot_text)
        if m:
            count = m.group(1).replace(',', '')
        if count is None:
            # Pattern 2: line starts with 'MonthName' then number
            p2 = re.compile(rf'^{mname}[\s\-:,]+([0-9,]+)', re.I)
            for ln in lines:
                m2 = p2.match(ln)
                if m2:
                    count = m2.group(1).replace(',', '')
                    break
        if count is None:
            # Pattern 3: ISO token like 2022-05 on same line with number
            iso_pat = re.compile(rf'2022[-/]{mm}[^\n\r]*([0-9,]+)')
            m3 = iso_pat.search(snapshot_text)
            if m3:
                count = m3.group(1).replace(',', '')
        if count is None:
            # Pattern 4: month name in a line, look 1-2 lines ahead for a number
            for idx, ln in enumerate(lines):
                if re.search(rf'\b{mname}\b', ln, re.I):
                    for j in range(1, 3):
                        if idx + j < len(lines):
                            nums = re.findall(r'([0-9,]+)', lines[idx + j])
                            if nums:
                                count = nums[0].replace(',', '')
                                break
                    if count:
                        break
        if count:
            results[mm] = count

    # 6) Print results in MM:COUNT format for 05..12, one per line
    for mm in ['05', '06', '07', '08', '09', '10', '11', '12']:
        print(f"{mm}:{results.get(mm, '0')}")

